'use strict';
/* public/js/65-net.js -- WebSocket client, remote players, server messages, play-test log batching. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- multiplayer (WebSocket to the camp server) ---------- */
const net={ws:null,id:null,retry:1000,last:0,lastPos:'',lastPosT:0,day:1,typed:'',needPass:false,passOk:false,awaitingJoin:false};
const remotes=new Map();
let DIRINFO=null; // last 'dirinfo' snapshot from the server (see the 'events' console command in 76-console.js)
function wsSend(o){if(net.ws&&net.ws.readyState===1)try{net.ws.send(JSON.stringify(o))}catch(e){}}
let HOST='',PASS='';
try{
  const sp=new URLSearchParams(location.search),qh=sp.get('host'),qc=sp.get('camp');
  if(qh)localStorage.setItem('cgl-host',qh);
  if(qc)localStorage.setItem('cgl-camp',qc); // invite link: ?camp=<password>, like ?host= for the host token
  if(qh||qc)history.replaceState(null,'',location.pathname);
  HOST=localStorage.getItem('cgl-host')||'';PASS=localStorage.getItem('cgl-camp')||'';
}catch(e){}
if(PASS)campIn.value=PASS;
function sendJoin(){wsSend({t:'join',n:S.name,c:S.color,v:2,fresh:!S.resumed&&!S.restored,host:HOST||undefined,p:PASS||undefined})}
function sendPresence(now){
  if(!S.started||now-net.last<100)return;net.last=now;
  const dep=holeDepthHere(),fl=(P.crouch&&dep>0.95?1:0)|(S.ko?2:0)|(S.light?4:0)|(P.crouch?8:0)|(isTrapped()?16:0)|(inSinkhole()?32:0)|(sinkPulling?64:0)|(vSt>=3&&vSt<=4?128:0);
  const pos=[+P.x.toFixed(2),+P.y.toFixed(2),+P.z.toFixed(2),+P.fa.toFixed(2),S.ko?3:P.anim,fl,S.carry==null?-1:S.carry,+S.noise.toFixed(1),myLevel(),S.tent];
  const key=pos.join(',');if(key===net.lastPos&&now-net.lastPosT<1000)return;
  net.lastPos=key;net.lastPosT=now;wsSend({t:'pos',x:pos[0],y:pos[1],z:pos[2],r:pos[3],a:pos[4],f:pos[5],cy:pos[6],nz:pos[7],lv:pos[8],room:pos[9],sc:S.seeds,hp:Math.round(S.hp),wt:Math.round(S.water)});
}

/* ---------- play-test logging: queue events and send them to the server in one small batch every ~1.5s
   (see logger.js for the full field list, and scripts/logq.js to query them). Solo/offline play just skips
   sending: there's no server to write the file. Never lets a logging bug break the game. ---------- */
const LOGQ=[];
function logEv(k,fields){try{if(!online()||LOGQ.length>=80)return;LOGQ.push(Object.assign({k},fields))}catch(e){}}
function flushLog(){try{if(LOGQ.length&&online())wsSend({t:'log',ev:LOGQ.splice(0,24)})}catch(e){}}
setInterval(flushLog,1500);
addEventListener('error',e=>{try{logEv('err',{msg:String((e&&(e.message||(e.error&&e.error.message)))||'error').slice(0,300),src:(e&&e.filename)||'',line:(e&&e.lineno)||0,col:(e&&e.colno)||0,stack:(e&&e.error&&e.error.stack)?String(e.error.stack).slice(0,600):''})}catch(err){}});
addEventListener('unhandledrejection',e=>{try{const r=e&&e.reason;logEv('err',{msg:'unhandledrejection: '+String((r&&r.message)||r||'').slice(0,300),stack:(r&&r.stack)?String(r.stack).slice(0,600):''})}catch(err){}});
function num(v,a,b,d){v=Number(v);return Number.isFinite(v)?clamp(v,a,b):d}
function addRemote(m){
  if(m.id===net.id)return null;if(remotes.has(m.id))return null;
  const ci=num(m.c,0,CAMPER_COLORS.length-1,0)|0;const name=cleanName(m.n)||'Camper';
  const p=makePerson(playerLook(name,ci));scene.add(p.g);
  const R={p,L:makeLabel(p.g,name,''),name,ci,f:num(m.f,0,255,0)|0,room:Number.isInteger(m.room)?m.room:null,lv:0,tx:num(m.x,-HALF-20,HALF+20,0),ty:num(m.y,-5,10,0),tz:num(m.z,-HALF-20,HALF+20,40),tr:num(m.r,-10,10,0),anim:num(m.a,0,4,0)|0,dph:0,hp:num(m.hp,0,100,100)};
  p.g.position.set(R.tx,R.ty,R.tz);remotes.set(m.id,R);setRemoteLv(R,m.lv);renderOnline();return R;
}
function setRemoteLv(R,lv){lv=num(lv,1,99,1)|0;if(R.lv===lv)return;R.lv=lv;R.L.n.textContent=`${R.name} · LV ${lv}`;setHat(R.p,lv)}
function removeRemote(id){const R=remotes.get(id);if(!R)return null;scene.remove(R.p.g);R.L.el.remove();labeled.splice(labeled.indexOf(R.L),1);remotes.delete(id);dropVoicePeer(id);renderOnline();return R}
function applyDig(x,z,d,rebuild){
  x=r1(num(x,-EDGE,EDGE,0));z=r1(num(z,-EDGE,EDGE,0));d=num(d,0,EIGHT_FT,0);
  let h=holeNear(x,z,0.06);
  if(h){if(d<=h.d+0.001)return;h.d=d;if(!h.mine)h.remote=true}else h=addHole({x,z,d,remote:true});
  if(rebuild){touchHole(h);if(nearCam(x,z,40))puff(x,groundAt(x,z)+0.4,z,h.mx,h.mz,4)}
}
function renderOnline(){
  const names=[...remotes.values()].map(R=>R.name);
  const lob=$('#lobby');
  if(net.ws&&net.ws.readyState===1)lob.textContent=names.length?`${names.length} other camper${names.length>1?'s':''} digging right now: ${names.join(', ')}.`:'Nobody else is here yet. Send your friends this link. The D Tent crew will keep you company.';
  $('#onlineList').textContent=names.length?['You',...names].join(', '):'Just you';
}
function wonAlready(name){if(S.won)return;S.won=true;rain.visible=true;setTimeout(()=>toast(`${name} already dug up the suitcase today. A new day starts soon.`,'gold',6000),1500)}
function onMsg(m){
  if(!m||typeof m!=='object')return;
  switch(m.t){
    case 'hello':{
      net.id=m.id;net.day=num(m.day,1,99999,1)|0;$('#dayTag').textContent='Day '+net.day;if(m.clock)setClock(m.clock);
      if(Array.isArray(m.iceServers)&&m.iceServers.length)ICE_SERVERS=m.iceServers;
      for(const id of [...remotes.keys()])removeRemote(id);
      if(Array.isArray(m.holes)){for(const e of m.holes.slice(0,40000))if(Array.isArray(e))applyDig(e[0],e[1],e[2],false);rebuildRegion(-HALF,-HALF,HALF,HALF)}
      if(Array.isArray(m.got))for(const i of m.got){const it=items[i|0];if(it)it.found=true}
      if(m.kb)reveal(cleanName(m.kb)||'A camper');
      if(Array.isArray(m.peers))for(const p of m.peers)addRemote(p);
      for(const id of [...PROPS.keys()])removeProp(id);for(const id of [...BAGS.keys()])removeBag(id);
      if(Array.isArray(m.props))for(const p of m.props.slice(0,60))if(p)addProp(num(p.id,0,1e5,-1)|0,String(p.type),num(p.x,-600,600,0),num(p.z,-600,600,0));
      if(Array.isArray(m.bags))for(const b of m.bags.slice(0,80))if(b)addBag(num(b.id,0,1e9,-1),num(b.x,-600,600,0),num(b.z,-600,600,0),Array.isArray(b.items)?b.items.filter(t=>LOOT[t]).slice(0,12):[],cleanName(b.n));
      if(m.won)wonAlready(cleanName(m.won)||'A camper');
      // Ground truth for the monsters, straight from the server: a first connect starts clean anyway, but a
      // reconnect could otherwise be left rendering whatever it saw right before the socket dropped (it might
      // have missed the one broadcast that told everyone else the monster was gone).
      monFromServer(m.mon||{trucks:[],zer:null});
      // event director state: whether it's running, and any of its events already in progress (twister can't be
      // replayed mid-flight -- see supportsLateJoin in public/director.js -- so only kinds like landslide show up here).
      if(typeof m.dirOn==='boolean')DIRECTOR_ON=m.dirOn;
      if(Array.isArray(m.dirEvents))for(const e of m.dirEvents.slice(0,8))if(e&&typeof e.k==='string')spawnEnv(e.k,{x:num(e.x,-600,600,0),z:num(e.z,-600,600,0),a:0,t0:e.t0});
      javFromServer(m.jav||[]); // ditto for the javelina herd, if one's out there right now
      lionFromServer(m.mon||{});   // same ground-truth-on-(re)connect reasoning as monFromServer, for the mountain lion
      net.passOk=true;campWrap.hidden=true;hideCampErr();startBtn.disabled=false;
      renderOnline();if(S.started){sendJoin();if(S.hasKB){const kb=items.find(i=>i.type==='kb');wsSend({t:'got',item:kb.id,kb:true})}}
      maybeResume();break;
    }
    // A reconnect (including the join-timeout closing an idle title screen) re-sends 'needpass'; only prefill
    // from the remembered/invite-link password when the field is still empty, so it never clobbers what
    // someone's mid-typing or a value we already know was rejected.
    case 'needpass':net.needPass=true;campWrap.hidden=false;startBtn.disabled=false;if(PASS&&!campIn.value)campIn.value=PASS;break;
    case 'joinrejected':
      net.awaitingJoin=false;
      if(!S.started){showCampErr(m.reason||'Wrong camp password');PASS='';}else toast(m.reason||'Wrong camp password','bad',4000);
      break;
    case 'join':{const R=addRemote(m);if(R)toast(`${R.name} showed up at camp.`,'good',3000);break}
    case 'leave':{const R=removeRemote(m.id);if(R)toast(`${R.name} left camp.`,'',2500);break}
    case 'pos':{const R=remotes.get(m.id);if(!R)break;R.tx=num(m.x,-HALF-20,HALF+20,R.tx);R.ty=num(m.y,-5,10,R.ty);R.tz=num(m.z,-HALF-20,HALF+20,R.tz);R.tr=num(m.r,-10,10,R.tr);R.anim=num(m.a,0,4,0)|0;R.f=num(m.f,0,255,0)|0;R.hp=num(m.hp,0,100,R.hp);R.room=Number.isInteger(m.room)?m.room:null;setRemoteLv(R,m.lv);break}
    case 'dig':applyDig(m.x,m.z,m.d,true);break;
    case 'got':{const it=items[m.item|0];if(it)it.found=true;break}
    case 'ungot':{const it=items[m.item|0];if(it)it.found=false;break}
    case 'say':{const R=remotes.get(m.id);if(R){say(R.L,SHOUTS[num(m.i,0,SHOUTS.length-1,0)|0]);sfx.shout();R.p.waveT=1.4}break}
    case 'kb':reveal(cleanName(m.n)||'A camper');break;
    case 'win':triggerWin(cleanName(m.n)||'A camper',false);break;
    case 'restore':if(S.started&&!S.resumed&&!S.restored){S.restored=true;const sc=num(m.sc,0,1e6,0)|0;if(sc>S.seeds){S.seeds=sc;toast('Welcome back. Your '+sc+' seeds were saved.','good',4000)}P.x=num(m.x,-HALF+3,HALF-3,P.x);P.z=num(m.z,-HALF+3,HALF-3,P.z);P.y=groundAt(P.x,P.z)}break;
    case 'update':saveSession();setTimeout(()=>location.reload(),300);break;
    case 'party':startParty(m.id,cleanName(m.n)||'Camper',num(m.dur,5,300,60));break;
    case 'nodisco':toast(m.busy?'A dance party is already going. Get over there.':'The camp is still tired from your last party. Try again in a few minutes.','',3500);break;
    case 'run':setRun(m);break;
    case 'quota':setRun(m);quotaMet();break;
    case 'grace':graceDay();break;
    case 'fired':fired(num(m.bank,0,1e7,0)|0,num(m.quota,0,1e7,0)|0);break;
    case 'prog':{const xp=num(m.xp,0,1e8,0);if(xp>PROG.xp){PROG.xp=xp;saveProg();if(me){setHat(me,myLevel());meL.n.textContent=myTag()}}break}
    case 'mon':monFromServer(m);lionFromServer(m);break;
    case 'jav':javFromServer(m.list,m.ev);break;
    case 'prop':addProp(num(m.id,0,1e5,-1)|0,String(m.type),num(m.x,-600,600,0),num(m.z,-600,600,0));break;
    case 'props':if(Array.isArray(m.list))for(const a of m.list){const pr=PROPS.get(a[0]);if(pr){pr.x=num(a[1],-600,600,pr.x);pr.z=num(a[2],-600,600,pr.z);pr.n=num(a[3],0,40,0)|0}}break;
    case 'psold':propSold(num(m.id,0,1e5,-1)|0,num(m.v,0,1e4,0)|0,Array.isArray(m.who)?m.who:[]);break;
    case 'bag':addBag(num(m.id,0,1e9,-1),num(m.x,-600,600,0),num(m.z,-600,600,0),Array.isArray(m.items)?m.items.filter(t=>LOOT[t]).slice(0,12):[],cleanName(m.n));break;
    case 'bagGone':removeBag(num(m.id,0,1e9,-1));break;
    case 'grabbed':removeBag(num(m.id,0,1e9,-1));if(Array.isArray(m.items))takeBag(m.items.slice(0,12),cleanName(m.n));break;
    case 'revived':revived(cleanName(m.by)||'A friend');break;
    case 'bonked':{const R=remotes.get(m.from);bonked(cleanName(m.by)||'A camper',R?P.x-R.p.g.position.x:num(m.dx,-1,1,0),R?P.z-R.p.g.position.z:num(m.dz,-1,1,0));break}
    case 'pulled':if(isTrapped()){popOut();toast(`${cleanName(m.by)||'A friend'} pulled you out of the hole.`,'good',2500)}break;
    case 'sinkpulled':addXP(SINK_RESCUE_XP);toast(`You helped pull ${cleanName(m.by)||'a friend'} out of the sinkhole! +${SINK_RESCUE_XP} XP`,'good',2800);sfx.thud();logEv('sinkRescuer',{by:cleanName(m.by)||''});break;
    case 'ping':{const mine=m.id===net.id,R=remotes.get(m.id);if(!mine&&!R)break;pingAt(num(m.x,-600,600,0),num(m.z,-600,600,0),mine?'You':R.name,mine?0xffd23a:CAMPER_COLORS[R.ci]);break}
    case 'chat':{const R=remotes.get(m.id);if(R&&typeof m.s==='string'){say(R.L,m.s.slice(0,80),7000);tone(700,0.06,'triangle',0.05)}break}
    case 'rtc':handleRtc(num(m.from,0,1e9,-1)|0,m.d);break;
    case 'host':
      net.host=m.on===true;if(!net.host)$('#admin').hidden=true;$('#conBtn').hidden=!(net.host&&isTouch);
      // 'host' is only ever sent after a join clears the password gate, so seeing it after our probe join
      // means the password was right: remember it and start (or resume) the game for real.
      if(net.awaitingJoin){net.awaitingJoin=false;net.passOk=true;try{localStorage.setItem('cgl-camp',PASS)}catch(e){}hideCampErr();if(pendingResume)maybeResume();else startGame()}
      break;
    case 'env':spawnEnv(m.k,{x:m.x,z:m.z,a:m.a,t0:m.t0,dir:m.dir===true},m.dir?null:(cleanName(m.n)||'A camper'));break; // m.dir: director-spawned, no "camper spawned" toast
    case 'dir':DIRECTOR_ON=m.on===true;break; // host toggled the event director (see the 'director' console command)
    case 'dirinfo':DIRINFO=m;break; // periodic director status snapshot, for the 'events' console command
    case 'clock':setClock(m);break;
    case 'sleepstat':SLEEP.asleep=num(m.asleep,0,80,0)|0;SLEEP.total=num(m.total,0,80,1)|0;break;
    case 'daybreak':S.inBed=null;toast('Morning already - everyone in camp was asleep.','good',4500);break;
    case 'reset':toast('A new day at Camp Green Lake. The lake bed is being refilled.','',4000);saveSession(true);setTimeout(()=>location.reload(),2500);break;
  }
}
// A saved session (e.g. the page reloaded itself after a server 'reset'/'update', or just an accidental refresh)
// normally resumes straight away. When a camp password is set we still have to clear that gate first, so this
// waits for word from the server (hello = no password needed / host-after-password = password accepted) before
// resuming, with a short fallback timer in case that word never arrives (server down, odd network).
let pendingResume=null;
{const R0=loadSession();if(R0)pendingResume=R0}
function maybeResume(){
  if(!pendingResume||S.started)return;
  if(net.needPass&&!net.passOk)return; // password required and not yet cleared: let the title screen ask for it
  const r=pendingResume;pendingResume=null;startGame(r);
}
function connect(){
  if(!/^https?:$/.test(location.protocol)){$('#lobby').textContent='Offline copy. Solo camp.';startBtn.disabled=false;maybeResume();return}
  let ws;try{ws=new WebSocket((location.protocol==='https:'?'wss:':'ws:')+'//'+location.host+'/ws')}catch(e){startBtn.disabled=false;maybeResume();return}
  net.ws=ws;
  ws.onopen=()=>{net.retry=1000;clearTimeout(net.lostT)};
  ws.onmessage=e=>{let m;try{m=JSON.parse(e.data)}catch(_){return}onMsg(m)};
  ws.onclose=()=>{for(const id of [...remotes.keys()])removeRemote(id);$('#lobby').textContent='Reconnecting to camp…';clearTimeout(net.lostT);net.lostT=setTimeout(()=>{if(S.started)toast('Lost connection to camp. Reconnecting…','bad',2500)},3000);setTimeout(connect,net.retry);net.retry=Math.min(net.retry*2,15000)};
}
connect();
function updateRemotes(dt){
  for(const[id,R]of remotes){
    if(PARTY.on&&id!==PARTY.targetId)continue;
    const g=R.p.g,k=Math.min(1,dt*10);
    g.visible=R.room===S.tent;
    const dx=R.tx-g.position.x,dz=R.tz-g.position.z;
    if(dx*dx+dz*dz>100){g.position.set(R.tx,R.ty,R.tz)}else{g.position.x+=dx*k;g.position.z+=dz*k;g.position.y+=(R.ty-g.position.y)*k}
    let dr=R.tr-g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));g.rotation.y+=dr*k;
    R.dph=(R.dph+dt/0.42)%1;
    if(R.anim===3&&R.room!=null){   // lying down inside a tent = asleep in a bunk: snap onto the nearest one in that room
      let bk=null,bd=9;for(const u of BUNKS)if(u.tent===R.room){const d=(u.x-R.tx)**2+(u.z-R.tz)**2;if(d<bd){bd=d;bk=u}}
      if(bk){animPerson(R.p,0,dt);sleepPose(R.p,bk);continue}
    }
    if(R.p.g.rotation.x===-Math.PI/2&&R.anim!==3)R.p.g.rotation.x=0;   // got up out of a bunk
    animPerson(R.p,R.anim,dt,R.dph);
  }
}
